-- Generated by scripts/mapping/build-civ-mapping.mjs from scripts/mapping/civ-draft.mjs. Don't edit by hand.
-- The civilization mapping (CONTRACTS 14, 16): each civilization ability's bullets and the modifiers behind them,
-- matched by the modifiers' effects, arguments and requirements against the bullet text of the civilization's own
-- age (the Antiquity database for Antiquity civilizations, the age modules for Exploration and Modern ones). Bullets
-- one effect serves together are merged (BulletCount > 1). A Movable 0 row goes with a civic or a unique
-- (LShufCivGoesWith) and is never dealt. INSERT OR IGNORE only, no foreign
-- keys to game tables, so this file runs in both the gameplay and the config database and can run twice.
CREATE TABLE IF NOT EXISTS LShufCivMapping (
  PieceId TEXT NOT NULL PRIMARY KEY,
  CivilizationType TEXT NOT NULL,
  Age TEXT,
  AbilityTrait TEXT NOT NULL,
  DescriptionKey TEXT,
  Kind TEXT NOT NULL,
  BulletIndex INTEGER,
  BulletCount INTEGER NOT NULL DEFAULT 1,
  BulletText TEXT,
  BiasTags TEXT,
  Value INTEGER NOT NULL DEFAULT 1,
  SpecificTo TEXT,
  Movable INTEGER NOT NULL DEFAULT 1,
  Reviewed INTEGER NOT NULL DEFAULT 1,
  Guess INTEGER NOT NULL DEFAULT 1,
  Note TEXT
);
CREATE TABLE IF NOT EXISTS LShufCivMappingModifiers (
  PieceId TEXT NOT NULL,
  ModifierId TEXT NOT NULL,
  Role TEXT NOT NULL,
  PRIMARY KEY (PieceId, ModifierId)
);
-- CONTRACTS 31. A piece that stays with a civic or a unique, and the build card it goes with.
CREATE TABLE IF NOT EXISTS LShufCivGoesWith (
  PieceId TEXT NOT NULL PRIMARY KEY,
  GoesWithId TEXT NOT NULL
);
-- A piece the game implements outside the ability: the home trait the game's own rows name, and each modifier whose
-- unlock or requirement names it. The apply points them at a trait whoever holds the piece carries.
CREATE TABLE IF NOT EXISTS LShufCivRulePieces (
  PieceId TEXT NOT NULL,
  HomeTrait TEXT NOT NULL,
  TargetModifier TEXT NOT NULL,
  PRIMARY KEY (PieceId, TargetModifier)
);
-- A civilization played outside its own age (Test of Time): the modifiers that age attaches in place of a piece's
-- own (Spain's coastal yields under their Antiquity and Modern ids). The apply copies whichever of a piece's own and
-- age modifiers the loaded database attaches to the giver's ability.
CREATE TABLE IF NOT EXISTS LShufCivMappingAgeModifiers (
  PieceId TEXT NOT NULL,
  Age TEXT NOT NULL,
  ModifierId TEXT NOT NULL,
  Role TEXT NOT NULL,
  PRIMARY KEY (PieceId, Age, ModifierId)
);
-- A movable piece that does nothing in an age other than its civilization's own: the age attaches none of its
-- modifiers, own or stand-in (the game drops the bullet there), or it's a favored wonder or a rule of another age.
-- It stays out of that age's deal and build cards.
CREATE TABLE IF NOT EXISTS LShufCivPieceDead (
  PieceId TEXT NOT NULL,
  Age TEXT NOT NULL,
  PRIMARY KEY (PieceId, Age)
);
-- Where a piece's text is in another age's wording of the ability (the game scales the numbers by age): that age's
-- description key and bullet. Only the pieces whose text differs there; the rest read their own.
CREATE TABLE IF NOT EXISTS LShufCivMappingAgeText (
  PieceId TEXT NOT NULL,
  Age TEXT NOT NULL,
  DescriptionKey TEXT NOT NULL,
  BulletIndex INTEGER NOT NULL,
  BulletCount INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (PieceId, Age)
);

INSERT OR IGNORE INTO LShufCivMapping (PieceId, CivilizationType, Age, AbilityTrait, DescriptionKey, Kind, BulletIndex, BulletCount, BulletText, BiasTags, Value, SpecificTo, Movable, Reviewed, Guess, Note) VALUES
