  ('CIVILIZATION_ABBASID__B02', 'CIVILIZATION_ABBASID', 'AGE_EXPLORATION', 'TRAIT_ABBASID_ABILITY', 'LOC_TRAIT_ABBASID_ABILITY_DESCRIPTION', 'bullet', 2, 1, '[B]+20% [icon:YIELD_PRODUCTION] Production[/B] towards constructing [icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] in [icon:YIELD_CITIES] Cities with at least [B]5 [icon:SPECIALIST] Specialists[/B].', NULL, 2, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_ABBASID__B03', 'CIVILIZATION_ABBASID', 'AGE_EXPLORATION', 'TRAIT_ABBASID_ABILITY', 'LOC_TRAIT_ABBASID_ABILITY_DESCRIPTION', 'bullet', 3, 1, '[B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing the House of Wisdom.', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_AKSUM__B01', 'CIVILIZATION_AKSUM', 'AGE_ANTIQUITY', 'TRAIT_AKSUM_ABILITY', 'LOC_TRAIT_AKSUM_ABILITY_DESCRIPTION', 'bullet', 1, 1, '+3 [icon:YIELD_GOLD] Gold on [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP] in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] adjacent to Coast.', '|COAST|', 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_AKSUM__B02', 'CIVILIZATION_AKSUM', 'AGE_ANTIQUITY', 'TRAIT_AKSUM_ABILITY', 'LOC_TRAIT_AKSUM_ABILITY_DESCRIPTION', 'bullet', 2, 1, '+1 [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP] Limit with other Civilizations, and all Civilizations have +1 [icon:TRADE_ROUTE] Trade Route Limit with you.', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_AKSUM__B03', 'CIVILIZATION_AKSUM', 'AGE_ANTIQUITY', 'TRAIT_AKSUM_ABILITY', 'LOC_TRAIT_AKSUM_ABILITY_DESCRIPTION', 'bullet', 3, 1, '[icon:TRADE_ROUTE] Trade Routes to or from your Settlements have unlimited [TIP:LOC_PEDIA_CONCEPTS_TRADE_RANGE_TOOLTIP]Range[/TIP].', NULL, 2, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_AKSUM__B04', 'CIVILIZATION_AKSUM', 'AGE_ANTIQUITY', 'TRAIT_AKSUM_ABILITY', 'LOC_TRAIT_AKSUM_ABILITY_DESCRIPTION', 'bullet', 4, 1, '+30% [icon:YIELD_PRODUCTION] Production towards constructing the Great Stele.', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
