  ('CIVILIZATION_AMERICA__B02', 'CIVILIZATION_AMERICA', 'AGE_MODERN', 'TRAIT_AMERICA_ABILITY', 'LOC_TRAIT_AMERICA_ABILITY_DESCRIPTION', 'bullet', 2, 1, '+1 [icon:YIELD_PRODUCTION] Production on [icon:RADIAL_RESOURCES] [B]Resources.[/B]', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_AMERICA__B03', 'CIVILIZATION_AMERICA', 'AGE_MODERN', 'TRAIT_AMERICA_ABILITY', 'LOC_TRAIT_AMERICA_ABILITY_DESCRIPTION', 'bullet', 3, 1, '+30% [icon:YIELD_PRODUCTION] Production towards constructing the Statue of Liberty.', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
