  ('CIVILIZATION_ASSYRIA__B02', 'CIVILIZATION_ASSYRIA', 'AGE_ANTIQUITY', 'TRAIT_ASSYRIA_ABILITY', 'LOC_TRAIT_ASSYRIA_ABILITY_DESCRIPTION', 'bullet', 2, 1, '[icon:NAR_REW_GREATWORK] [B][TIP:LOC_PEDIA_CONCEPTS_CODEX_TOOLTIP]Codices[/TIP][/B] are not awarded from [B][TIP:LOC_PEDIA_CONCEPTS_TECH_TOOLTIP]Technologies[/TIP][/B].', NULL, 1, NULL, 1, 1, 1, 'Rule: the codex rewards'' exception follows whoever holds this piece (CONTRACTS 31).'),
