  ('CIVILIZATION_MEXICO__B01', 'CIVILIZATION_MEXICO', 'AGE_MODERN', 'TRAIT_MEXICO_ABILITY', 'LOC_TRAIT_MEXICO_ABILITY_DESCRIPTION', 'bullet', 1, 1, 'Starts with a unique [icon:GOVERNMENT] [TIP:LOC_PEDIA_CONCEPTS_GOVERNMENT_TOOLTIP]Government[/TIP], Revolución. This Government''s passive effect is +6 [icon:YIELD_HAPPINESS] Happiness in Cities for every Tradition slotted in the Government. It starts with one [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebration[/TIP] effect, +2[icon:YIELD_CULTURE] Culture in Happy Settlements, or +6 in Joyous Settlements, or +10 in Ecstatic Settlements for 6 turns. Cannot enter any other Government type.', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_MEXICO__B02', 'CIVILIZATION_MEXICO', 'AGE_MODERN', 'TRAIT_MEXICO_ABILITY', 'LOC_TRAIT_MEXICO_ABILITY_DESCRIPTION', 'bullet', 2, 1, '+100% [icon:CULTURE_VP] [TIP:LOC_PEDIA_CONCEPTS_TOURISTS_TOOLTIP]Tourism[/TIP] from [icon:CELEBRATION] [TIP:LOC_PEDIA_CONCEPTS_CELEBRATIONS_TOOLTIP]Celebrations[/TIP].', NULL, 2, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_MEXICO__B03', 'CIVILIZATION_MEXICO', 'AGE_MODERN', 'TRAIT_MEXICO_ABILITY', 'LOC_TRAIT_MEXICO_ABILITY_DESCRIPTION', 'bullet', 3, 1, '+30% [icon:YIELD_PRODUCTION] Production towards constructing Palacio de Bellas Artes.', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_MING__B01', 'CIVILIZATION_MING', 'AGE_EXPLORATION', 'TRAIT_MING_ABILITY', 'LOC_TRAIT_MING_ABILITY_DESCRIPTION', 'bullet', 1, 1, '[B]+50% [icon:YIELD_SCIENCE] Science[/B] in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP].', NULL, 4, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_MING__B02', 'CIVILIZATION_MING', 'AGE_EXPLORATION', 'TRAIT_MING_ABILITY', 'LOC_TRAIT_MING_ABILITY_DESCRIPTION', 'bullet', 2, 1, '[B]-15 [icon:YIELD_SCIENCE] Science[/B] per turn for each [icon:SOCIAL_POLICY] [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Social Policy[/TIP], but not [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP], slotted in the [icon:GOVERNMENT] [TIP:LOC_PEDIA_CONCEPTS_GOVERNMENT_TOOLTIP]Government[/TIP].', NULL, 1, NULL, 1, 1, 1, NULL),
