  ('CIVILIZATION_PIRATE_REPUBLIC__B01', 'CIVILIZATION_PIRATE_REPUBLIC', 'AGE_EXPLORATION', 'TRAIT_PIRATE_REPUBLIC_ABILITY', 'LOC_TRAIT_PIRATE_REPUBLIC_ABILITY_EX_DESCRIPTION', 'bullet', 1, 1, '[B]Naval Units, [icon:UNIT_TREASURE_FLEET] Treasure Convoys, and [icon:UNIT_BUCCANEER] Buccaneers[/B] can move into other [B]Civilization''s[/B] borders without being at [icon:WAR] [B]War[/B] or having [B]Open Borders[/B].', NULL, 2, NULL, 1, 1, 1, NULL),
