  ('CIVILIZATION_PIRATE_REPUBLIC__B03', 'CIVILIZATION_PIRATE_REPUBLIC', 'AGE_EXPLORATION', 'TRAIT_PIRATE_REPUBLIC_ABILITY', 'LOC_TRAIT_PIRATE_REPUBLIC_ABILITY_EX_DESCRIPTION', 'bullet', 3, 1, '[icon:UNIT_SETTLER] [B]Settlers[/B] cannot be trained or purchased, but you can capture other Civilizations'' [icon:UNIT_SETTLER] [B]Settlers[/B].', NULL, 2, NULL, 1, 1, 1, 'A card of its own on the build screen; in the random deal it goes with the Buccaneer and the settle charge (LShufBoundPieces, CONTRACTS 29).'),
  ('CIVILIZATION_PIRATE_REPUBLIC__B04', 'CIVILIZATION_PIRATE_REPUBLIC', 'AGE_EXPLORATION', 'TRAIT_PIRATE_REPUBLIC_ABILITY', 'LOC_TRAIT_PIRATE_REPUBLIC_ABILITY_EX_DESCRIPTION', 'bullet', 4, 1, '+5 [icon:ECONOMIC_VP] [TIP:LOC_PEDIA_CONCEPTS_GDP_TOOLTIP]GDP[/TIP] from your [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP] defeating other [B]Units[/B].', NULL, 2, NULL, 1, 1, 1, NULL),
