  ('CIVILIZATION_ROME__B01', 'CIVILIZATION_ROME', 'AGE_ANTIQUITY', 'TRAIT_ROME_ABILITY', 'LOC_TRAIT_ROME_ABILITY_DESCRIPTION', 'bullet', 1, 1, '+1 [icon:YIELD_CULTURE] Culture on [icon:CITY_URBAN] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Districts[/TIP] in the [icon:NOTIFICATION_SELECT_CAPITAL] Capital and City Centers in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP].', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_ROME__B02', 'CIVILIZATION_ROME', 'AGE_ANTIQUITY', 'TRAIT_ROME_ABILITY', 'LOC_TRAIT_ROME_ABILITY_DESCRIPTION', 'bullet', 2, 1, 'Gain a free [B]Infantry Unit[/B] in new [icon:YIELD_TOWNS] [B][TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP][/B] that you found.', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_ROME__B03', 'CIVILIZATION_ROME', 'AGE_ANTIQUITY', 'TRAIT_ROME_ABILITY', 'LOC_TRAIT_ROME_ABILITY_DESCRIPTION', 'bullet', 3, 1, '+30% [icon:YIELD_PRODUCTION] Production towards constructing the Colosseum.', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_RUSSIA__B01', 'CIVILIZATION_RUSSIA', 'AGE_MODERN', 'TRAIT_RUSSIA_ABILITY', 'LOC_TRAIT_RUSSIA_ABILITY_DESCRIPTION', 'bullet', 1, 1, '[B]+1 [icon:YIELD_CULTURE] Culture on [icon:CITY_UNIQUE_QUARTER] [TIP:LOC_PEDIA_CONCEPTS_QUARTER_TOOLTIP]Quarters[/TIP][/B] in [B][icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP][/B]. [B]+1 [icon:YIELD_SCIENCE] Science on [icon:CITY_UNIQUE_QUARTER] Quarters[/B] in [B][icon:YIELD_CITIES] Cities[/B] in [B]Tundra[/B].', '|BIOME_TUNDRA|', 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_RUSSIA__B02', 'CIVILIZATION_RUSSIA', 'AGE_MODERN', 'TRAIT_RUSSIA_ABILITY', 'LOC_TRAIT_RUSSIA_ABILITY_DESCRIPTION', 'bullet', 2, 1, '[B]+1 [icon:YIELD_FOOD] Food on Farms[/B] in [B][icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP][/B]. [B]+1 [icon:YIELD_PRODUCTION] Production on Farms[/B] in [B][icon:YIELD_TOWNS] Towns[/B] in [B]Tundra[/B], count as [icon:YIELD_WAREHOUSE] Warehouse Bonus.', '|BIOME_TUNDRA|', 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_RUSSIA__B03', 'CIVILIZATION_RUSSIA', 'AGE_MODERN', 'TRAIT_RUSSIA_ABILITY', 'LOC_TRAIT_RUSSIA_ABILITY_DESCRIPTION', 'bullet', 3, 1, '[B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing the [B]Hermitage[/B].', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_SENGOKU__B01', 'CIVILIZATION_SENGOKU', 'AGE_EXPLORATION', 'TRAIT_SENGOKU_ABILITY', 'LOC_TRAIT_SENGOKU_ABILITY_EX_DESCRIPTION', 'bullet', 1, 1, '[B]+1 [icon:YIELD_DIPLOMACY] Influence, +3[icon:YIELD_CULTURE] Culture and +3[icon:YIELD_SCIENCE] Science[/B]  for every [B][icon:UNIT_ARMY_COMMANDER] Army[/B] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Commander[/TIP] XP earned in Combat.', NULL, 3, NULL, 1, 1, 1, 'The data gives +2 Culture and +2 Science per XP; the text says +3.'),
  ('CIVILIZATION_SENGOKU__B02', 'CIVILIZATION_SENGOKU', 'AGE_EXPLORATION', 'TRAIT_SENGOKU_ABILITY', 'LOC_TRAIT_SENGOKU_ABILITY_EX_DESCRIPTION', 'bullet', 2, 1, '[B][icon:YIELD_CULTURE] Culture[/B] [B][icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP][/B] no longer receive an Adjacency with [B][icon:CITY_UNIMPROVED] Mountain Terrain[/B].', NULL, 1, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SENGOKU__B03', 'CIVILIZATION_SENGOKU', 'AGE_EXPLORATION', 'TRAIT_SENGOKU_ABILITY', 'LOC_TRAIT_SENGOKU_ABILITY_EX_DESCRIPTION', 'bullet', 3, 1, '[B][icon:YIELD_SCIENCE] Science[/B] [B][icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP][/B] no longer receive an Adjacency with [B][icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP][/B].', NULL, 1, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SENGOKU__B04', 'CIVILIZATION_SENGOKU', 'AGE_EXPLORATION', 'TRAIT_SENGOKU_ABILITY', 'LOC_TRAIT_SENGOKU_ABILITY_EX_DESCRIPTION', 'bullet', 4, 1, '[B]+30%[icon:YIELD_PRODUCTION] Production [/B]towards constructing [B]Himeji Castle[/B].[/LIST]', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_SHAWNEE__B01', 'CIVILIZATION_SHAWNEE', 'AGE_EXPLORATION', 'TRAIT_SHAWNEE_ABILITY', 'LOC_TRAIT_SHAWNEE_ABILITY_EX_DESCRIPTION', 'bullet', 1, 1, '[B]+2 [icon:YIELD_FOOD] Food[/B] on [icon:CITY_RURAL] [TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]Improvements[/TIP] and [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Districts[/TIP] on [icon:CITY_UNIMPROVED] [B]Minor and Navigable River Terrain[/B] in [B][TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP][/B] adjacent to [B]Navigable Rivers[/B].', '|TERRAIN_NAVIGABLE_RIVER|', 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SHAWNEE__B02', 'CIVILIZATION_SHAWNEE', 'AGE_EXPLORATION', 'TRAIT_SHAWNEE_ABILITY', 'LOC_TRAIT_SHAWNEE_ABILITY_EX_DESCRIPTION', 'bullet', 2, 1, '[B]+1 [icon:RADIAL_RESOURCES] Resource Capacity[/B] in the [B][icon:NOTIFICATION_SELECT_CAPITAL] Capital[/B] per [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] you are [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B] of.', NULL, 2, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SHAWNEE__B03', 'CIVILIZATION_SHAWNEE', 'AGE_EXPLORATION', 'TRAIT_SHAWNEE_ABILITY', 'LOC_TRAIT_SHAWNEE_ABILITY_EX_DESCRIPTION', 'bullet', 3, 1, '[B]+30%[icon:YIELD_PRODUCTION] Production[/B] towards constructing [B]Serpent Mound[/B].', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_SIAM__B01', 'CIVILIZATION_SIAM', 'AGE_MODERN', 'TRAIT_SIAM_ABILITY', 'LOC_TRAIT_SIAM_ABILITY_DESCRIPTION', 'bullet', 1, 1, 'Gains a [B]unique [icon:DIPLOMATIC_ACTION] Diplomatic Action[/B] Itsaraphab to immediately become [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B] of a [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] at a higher [icon:YIELD_DIPLOMACY] Influence cost than [icon:PROJECT] Befriend Independent.', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SIAM__B02', 'CIVILIZATION_SIAM', 'AGE_MODERN', 'TRAIT_SIAM_ABILITY', 'LOC_TRAIT_SIAM_ABILITY_DESCRIPTION', 'bullet', 2, 1, '[B]+3 [icon:YIELD_DIPLOMACY] Influence[/B] for every Civilization you are [B][icon:PLAYER_RELATIONSHIP_FRIENDLY] Friendly[/B] or [B][icon:PLAYER_RELATIONSHIP_HELPFUL] Helpful[/B] with.', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SIAM__B03', 'CIVILIZATION_SIAM', 'AGE_MODERN', 'TRAIT_SIAM_ABILITY', 'LOC_TRAIT_SIAM_ABILITY_DESCRIPTION', 'bullet', 3, 1, '[B]+12 [icon:CULTURE_VP] Tourism[/B] for every [B][TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] you are [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of.', NULL, 2, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SIAM__B04', 'CIVILIZATION_SIAM', 'AGE_MODERN', 'TRAIT_SIAM_ABILITY', 'LOC_TRAIT_SIAM_ABILITY_DESCRIPTION', 'bullet', 4, 1, '[B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing [B]Doi Suthep[/B].', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_SILLA__B01', 'CIVILIZATION_SILLA', 'AGE_ANTIQUITY', 'TRAIT_SILLA_ABILITY', 'LOC_TRAIT_SILLA_ABILITY_AQ_DESCRIPTION', 'bullet', 1, 1, 'When you form an [icon:PLAYER_RELATIONSHIP_ALLIANCE] [TIP:LOC_PEDIA_CONCEPTS_ALLIANCE_TOOLTIP]Alliance[/TIP], both Leaders receive a free [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP] from the other Leader''s [icon:NOTIFICATION_SELECT_CAPITAL] Capital; these [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Routes[/TIP] do not go away when the [icon:PLAYER_RELATIONSHIP_ALLIANCE] [TIP:LOC_PEDIA_CONCEPTS_ALLIANCE_TOOLTIP]Alliance[/TIP] ends.', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SILLA__B02', 'CIVILIZATION_SILLA', 'AGE_ANTIQUITY', 'TRAIT_SILLA_ABILITY', 'LOC_TRAIT_SILLA_ABILITY_AQ_DESCRIPTION', 'bullet', 2, 1, '[B]+1 [icon:YIELD_DIPLOMACY] Influence[/B] for [B]each Civilization[/B] you have at least [B]1 [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP][/B] with.', NULL, 2, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SILLA__B03', 'CIVILIZATION_SILLA', 'AGE_ANTIQUITY', 'TRAIT_SILLA_ABILITY', 'LOC_TRAIT_SILLA_ABILITY_AQ_DESCRIPTION', 'bullet', 3, 1, '[B]+30%[icon:YIELD_PRODUCTION] Production [/B]towards constructing [B]Emile Bell[/B].', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_SONGHAI__B01', 'CIVILIZATION_SONGHAI', 'AGE_EXPLORATION', 'TRAIT_SONGHAI_ABILITY', 'LOC_TRAIT_SONGHAI_ABILITY_DESCRIPTION', 'bullet', 1, 1, '[B]+2 [icon:RADIAL_RESOURCES][/B] [TIP:LOC_PEDIA_CONCEPTS_RESOURCE_CAPACITY_TOOLTIP]Resource Capacity[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] on [TIP:LOC_PEDIA_CONCEPTS_NAVIGABLE_RIVER_TOOLTIP]Navigable Rivers[/TIP].', '|TERRAIN_NAVIGABLE_RIVER|', 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SONGHAI__B02', 'CIVILIZATION_SONGHAI', 'AGE_EXPLORATION', 'TRAIT_SONGHAI_ABILITY', 'LOC_TRAIT_SONGHAI_ABILITY_DESCRIPTION', 'bullet', 2, 1, '[B]+1 [icon:YIELD_PRODUCTION] Production[/B] in [icon:YIELD_CITIES] Cities on Navigable Rivers for every [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP] assigned to them.', '|TERRAIN_NAVIGABLE_RIVER|', 3, NULL, 1, 1, 1, NULL);
INSERT OR IGNORE INTO LShufCivMapping (PieceId, CivilizationType, Age, AbilityTrait, DescriptionKey, Kind, BulletIndex, BulletCount, BulletText, BiasTags, Value, SpecificTo, Movable, Reviewed, Guess, Note) VALUES
  ('CIVILIZATION_SONGHAI__B03', 'CIVILIZATION_SONGHAI', 'AGE_EXPLORATION', 'TRAIT_SONGHAI_ABILITY', 'LOC_TRAIT_SONGHAI_ABILITY_DESCRIPTION', 'bullet', 3, 1, 'Can generate [TIP:LOC_PEDIA_CONCEPTS_HOMELANDS_TOOLTIP]Homelands[/TIP] [icon:UNIT_TREASURE_FLEET] [TIP:LOC_PEDIA_CONCEPTS_TREASURE_CONVOY_TOOLTIP]Treasure Convoys[/TIP] on Navigable Rivers after completing the Kanta [icon:CIVICS] [TIP:LOC_PEDIA_CONCEPTS_CIVIC_TOOLTIP]Civic[/TIP].', NULL, 1, NULL, 0, 1, 0, 'Goes with the Kanta civic, whose own modifiers make the convoys (CONTRACTS 31).'),
  ('CIVILIZATION_SONGHAI__B04', 'CIVILIZATION_SONGHAI', 'AGE_EXPLORATION', 'TRAIT_SONGHAI_ABILITY', 'LOC_TRAIT_SONGHAI_ABILITY_DESCRIPTION', 'bullet', 4, 1, '[B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing the Tomb of Askia.', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_SPAIN__B01', 'CIVILIZATION_SPAIN', 'AGE_EXPLORATION', 'TRAIT_SPAIN_ABILITY', 'LOC_TRAIT_SPAIN_ABILITY_DESCRIPTION', 'bullet', 1, 1, '[B]+2 [icon:YIELD_FOOD] Food[/B], [B]+2 [icon:YIELD_GOLD] Gold[/B] and [B]+2 [icon:YIELD_PRODUCTION] Production[/B] in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] adjacent to Coast and in Settlements following your own [icon:NAR_REW_RELIGION] [TIP:LOC_PEDIA_CONCEPTS_RELIGION_TOOLTIP]Religion[/TIP], or +4 if it is both. Doubled in Settlements in [TIP:LOC_PEDIA_CONCEPTS_DISTANT_LANDS_TOOLTIP]Distant Lands[/TIP].', '|COAST|', 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SPAIN__B02', 'CIVILIZATION_SPAIN', 'AGE_EXPLORATION', 'TRAIT_SPAIN_ABILITY', 'LOC_TRAIT_SPAIN_ABILITY_DESCRIPTION', 'bullet', 2, 1, '[B]+15% [icon:YIELD_GOLD] Gold[/B] towards converting a [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Town[/TIP] to a [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]City[/TIP], or [B]+30% [icon:YIELD_GOLD] Gold[/B] in Settlements in Distant Lands.', NULL, 2, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_SPAIN__B03', 'CIVILIZATION_SPAIN', 'AGE_EXPLORATION', 'TRAIT_SPAIN_ABILITY', 'LOC_TRAIT_SPAIN_ABILITY_DESCRIPTION', 'bullet', 3, 1, '[B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing El Escorial.', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).'),
  ('CIVILIZATION_TONGA__B01', 'CIVILIZATION_TONGA', 'AGE_ANTIQUITY', 'TRAIT_TONGA_ABILITY', 'LOC_TRAIT_TONGA_ABILITY_DESCRIPTION', 'bullet', 1, 1, '[B]+1[icon:YIELD_DIPLOMACY] Influence[/B] on the [B]Palace[/B] and [B]City Halls[/B] in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] adjacent to [B]Coast[/B].', '|TERRAIN_COAST|COAST|', 2, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_TONGA__B02', 'CIVILIZATION_TONGA', 'AGE_ANTIQUITY', 'TRAIT_TONGA_ABILITY', 'LOC_TRAIT_TONGA_ABILITY_DESCRIPTION', 'bullet', 2, 1, 'Receive a free [B][icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP][/B] from a new [B][icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP][/B] when you become their [B][TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP][/B].', NULL, 3, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_TONGA__B03', 'CIVILIZATION_TONGA', 'AGE_ANTIQUITY', 'TRAIT_TONGA_ABILITY', 'LOC_TRAIT_TONGA_ABILITY_DESCRIPTION', 'bullet', 3, 1, 'Cannot use the [icon:PROJECT] [B]City-State - Incorporate[/B] or in Distant Lands the [B]Levy Unit Action[/B].', NULL, 1, NULL, 1, 1, 1, NULL),
  ('CIVILIZATION_TONGA__B04', 'CIVILIZATION_TONGA', 'AGE_ANTIQUITY', 'TRAIT_TONGA_ABILITY', 'LOC_TRAIT_TONGA_ABILITY_DESCRIPTION', 'bullet', 4, 1, '[B]+30%[icon:YIELD_PRODUCTION] Production[/B] towards constructing [B]Ha''amonga ''a Maui[/B].', NULL, 1, NULL, 1, 1, 1, 'Wonder: dealt as +30% towards this civilization''s favored wonder, named (CONTRACTS 31).');

